-- 79 Paper Dolls: the doll's root carries a sprite_library (four outfits,
-- each a hat, coat, sleeve and boot) and every clothing part a
-- sprite_resolver. Sprite.set_label on the root changes the whole outfit;
-- on one category, a part at a time. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/79-paper-dolls.scene"
local OUTFITS = { "summer", "rain", "winter", "party" }
local captions = true
local doll, coat, hips, head, arm_l, arm_r, confetti, status
local tags, tag_texts = {}, {}
local worn = { hat = 1, coat = 1, sleeve = 1, boot = 1 }
local outfit, auto, clock, t, pop = 1, true, 0, 0, 0

local function show()
    for i = 1, #OUTFITS do
        local on = worn.hat == i and worn.coat == i and worn.boot == i
        Sprite.set_color(tags[i], 1, 1, on and 0.6 or 1, 1)
        Transform.set_scale(tags[i], on and 1.12 or 1, on and 1.12 or 1)
    end
    UI.set_text(status, "hat " .. OUTFITS[worn.hat] .. "   coat " .. OUTFITS[worn.coat] .. "   boots "
        .. OUTFITS[worn.boot] .. (auto and "   (auto)" or ""))
end

local function changed()
    pop = 1
    Particles.emit_burst(confetti, 30)
    show()
end

local function wear_outfit(i)
    outfit = i
    Sprite.set_label(doll, OUTFITS[i])
    for k, _ in pairs(worn) do worn[k] = i end
    changed()
end

local function wear(category, i)
    worn[category] = i
    -- On the root with a category: every part of that category (both
    -- sleeves, both boots); on a part alone, just that part.
    Sprite.set_label(doll, OUTFITS[i], category)
    if category == "coat" then
        worn.sleeve = i
        Sprite.set_label(doll, OUTFITS[i], "sleeve")
    end
    changed()
end

function init(entity)
    doll = Entity.find_by_name("Doll")
    coat = Entity.find_by_name("Coat")
    hips = Entity.find_by_name("Hips")
    head = Entity.find_by_name("Head")
    arm_l = Entity.find_by_name("ArmL")
    arm_r = Entity.find_by_name("ArmR")
    confetti = Entity.find_by_name("Confetti")
    status = Entity.find_by_name("Status")
    for i = 1, #OUTFITS do
        tags[i] = Entity.find_by_name("Tag" .. (i - 1))
        tag_texts[i] = Entity.find_by_name("TagText" .. (i - 1))
    end
    show()
end

function update(entity, dt)
    nav.tick(SCENE)
    t = t + dt
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("A") then auto = not auto; clock = 0; show() end
    if Input.is_key_just_pressed("O") then wear_outfit(outfit % #OUTFITS + 1) end
    if Input.is_key_just_pressed("1") then wear("hat", worn.hat % #OUTFITS + 1) end
    if Input.is_key_just_pressed("2") then wear("coat", worn.coat % #OUTFITS + 1) end
    if Input.is_key_just_pressed("3") then wear("boot", worn.boot % #OUTFITS + 1) end
    if auto then
        clock = clock + dt
        if clock > 2.6 then
            clock = 0
            wear_outfit(outfit % #OUTFITS + 1)
        end
    end
    -- She sways: the hips bob, the body leans, the arms swing, the head tilts.
    pop = math.max(0, pop - dt * 3)
    local s = 1 + 0.06 * math.sin(pop * 3.14159)
    Transform.set_scale(doll, s, s)
    Transform.set_position(hips, 0, 168.0 + math.abs(math.sin(t * 2.2)) * 6)
    Transform.set_rotation(coat, math.sin(t * 1.1) * 0.05)
    Transform.set_rotation(head, math.sin(t * 1.3 + 1) * 0.08)
    Transform.set_rotation(arm_l, -0.12 + math.sin(t * 2.2) * 0.12)
    Transform.set_rotation(arm_r, 0.12 - math.sin(t * 2.2 + 0.6) * 0.12)
end
